from functools import cmp_to_key


def _parse(version):
    """Return (major, minor, patch, prerelease identifiers) for a version."""
    without_build = version.split('+', 1)[0]
    core, sep, prerelease = without_build.partition('-')
    major, minor, patch = (int(part) for part in core.split('.'))
    if not sep:
        return major, minor, patch, None
    identifiers = []
    for identifier in prerelease.split('.'):
        if identifier.isdigit():
            identifiers.append((0, int(identifier)))
        else:
            identifiers.append((1, identifier))
    return major, minor, patch, identifiers


def _compare(left, right):
    l_major, l_minor, l_patch, l_pre = _parse(left)
    r_major, r_minor, r_patch, r_pre = _parse(right)

    if (l_major, l_minor, l_patch) != (r_major, r_minor, r_patch):
        return -1 if (l_major, l_minor, l_patch) < (r_major, r_minor, r_patch) else 1

    if l_pre is None and r_pre is None:
        return 0
    if l_pre is None:
        return 1
    if r_pre is None:
        return -1

    for l_id, r_id in zip(l_pre, r_pre):
        if l_id != r_id:
            return -1 if l_id < r_id else 1

    if len(l_pre) != len(r_pre):
        return -1 if len(l_pre) < len(r_pre) else 1
    return 0


def sort_versions(vs):
    """Sort semantic version strings by SemVer 2.0.0 precedence, lowest first."""
    return sorted(vs, key=cmp_to_key(_compare))
